CREATE TABLE IF NOT EXISTS `#__decarodraw_draws` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`title` VARCHAR(255) NOT NULL,`mode` VARCHAR(32) NOT NULL DEFAULT 'groups',`status` VARCHAR(32) NOT NULL DEFAULT 'draft',`source_component` VARCHAR(100) NULL,`source_entity` VARCHAR(100) NULL,`source_id` VARCHAR(191) NULL,`configuration` MEDIUMTEXT NULL,`algorithm_version` VARCHAR(64) NULL,`created` DATETIME NOT NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,`modified` DATETIME NULL,`modified_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),KEY `idx_status` (`status`),KEY `idx_source` (`source_component`,`source_entity`,`source_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarodraw_entries` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`draw_id` BIGINT UNSIGNED NOT NULL,`entry_key` VARCHAR(191) NOT NULL,`display_name` VARCHAR(255) NOT NULL,`source_component` VARCHAR(100) NULL,`source_entity` VARCHAR(100) NULL,`source_id` VARCHAR(191) NULL,`pot_key` VARCHAR(64) NULL,`seed_order` INT NULL,`metadata` MEDIUMTEXT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_draw_entry_key` (`draw_id`,`entry_key`),KEY `idx_draw_pot` (`draw_id`,`pot_key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarodraw_targets` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`draw_id` BIGINT UNSIGNED NOT NULL,`target_type` VARCHAR(64) NOT NULL,`target_key` VARCHAR(191) NOT NULL,`position_no` INT NULL,`metadata` MEDIUMTEXT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_draw_target` (`draw_id`,`target_type`,`target_key`,`position_no`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarodraw_assignments` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`draw_id` BIGINT UNSIGNED NOT NULL,`execution_no` INT UNSIGNED NOT NULL DEFAULT 1,`sequence_no` INT UNSIGNED NOT NULL,`entry_id` BIGINT UNSIGNED NOT NULL,`target_id` BIGINT UNSIGNED NOT NULL,`revealed_at` DATETIME NULL,`created` DATETIME NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_execution_sequence` (`draw_id`,`execution_no`,`sequence_no`),UNIQUE KEY `uq_execution_entry` (`draw_id`,`execution_no`,`entry_id`),KEY `idx_target` (`target_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarodraw_audit` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`draw_id` BIGINT UNSIGNED NOT NULL,`event_type` VARCHAR(100) NOT NULL,`actor_id` INT UNSIGNED NOT NULL DEFAULT 0,`payload` MEDIUMTEXT NULL,`created` DATETIME NOT NULL,PRIMARY KEY (`id`),KEY `idx_draw_created` (`draw_id`,`created`),KEY `idx_event_type` (`event_type`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
